def choose_framework(needs):
    if needs.get("explicit_graph") or needs.get("interrupts"):
        return "LangGraph"
    if needs.get("data_rag") and needs.get("query_engines"):
        return "LlamaIndex"
    if needs.get("openai_native") and needs.get("handoffs"):
        return "OpenAI Agents SDK"
    if needs.get("microsoft_stack"):
        return "Microsoft Agent Framework / Semantic Kernel"
    if needs.get("role_tasks"):
        return "CrewAI"
    return "LangChain or direct provider SDK"

print(choose_framework({"data_rag": True, "query_engines": True, "handoffs": False}))
print(choose_framework({"explicit_graph": True, "interrupts": True}))
